-- Hand-written data step: each piece of content becomes one text per locale, JSON text in the column it held. A page's own text is its page language's; a component's, an incident's and a maintenance window's the install language's, Arabic when none is stored.
UPDATE `components` SET `name` = json_object(CASE WHEN (SELECT `value` FROM `settings` WHERE `key` = 'install_language') = '"en"' THEN 'en' ELSE 'ar' END, `name`), `description` = CASE WHEN `description` IS NULL THEN NULL ELSE json_object(CASE WHEN (SELECT `value` FROM `settings` WHERE `key` = 'install_language') = '"en"' THEN 'en' ELSE 'ar' END, `description`) END;--> statement-breakpoint
UPDATE `incidents` SET `title` = json_object(CASE WHEN (SELECT `value` FROM `settings` WHERE `key` = 'install_language') = '"en"' THEN 'en' ELSE 'ar' END, `title`);--> statement-breakpoint
UPDATE `incident_updates` SET `message` = json_object(CASE WHEN (SELECT `value` FROM `settings` WHERE `key` = 'install_language') = '"en"' THEN 'en' ELSE 'ar' END, `message`);--> statement-breakpoint
UPDATE `maintenance_windows` SET `title` = json_object(CASE WHEN (SELECT `value` FROM `settings` WHERE `key` = 'install_language') = '"en"' THEN 'en' ELSE 'ar' END, `title`), `message` = json_object(CASE WHEN (SELECT `value` FROM `settings` WHERE `key` = 'install_language') = '"en"' THEN 'en' ELSE 'ar' END, `message`);--> statement-breakpoint
UPDATE `component_groups` SET `name` = json_object((SELECT `locale` FROM `status_pages` WHERE `status_pages`.`id` = `component_groups`.`page_id`), `name`);--> statement-breakpoint
UPDATE `status_pages` SET `title` = json_object(`locale`, `title`);--> statement-breakpoint
UPDATE `status_pages` SET `customization` = json_set(`customization`, '$.description', json_object(`locale`, json_extract(`customization`, '$.description'))) WHERE json_type(`customization`, '$.description') = 'text';--> statement-breakpoint
UPDATE `status_pages` SET `customization` = json_set(`customization`, '$.labels', json((SELECT json_group_object(`key`, json_object(`status_pages`.`locale`, `value`)) FROM json_each(`status_pages`.`customization`, '$.labels')))) WHERE json_type(`customization`, '$.labels') = 'object';--> statement-breakpoint
UPDATE `status_pages` SET `customization` = json_set(`customization`, '$.footerLinks', json((SELECT json_group_array(json_set(`value`, '$.label', json_object(`status_pages`.`locale`, json_extract(`value`, '$.label')))) FROM (SELECT `value` FROM json_each(`status_pages`.`customization`, '$.footerLinks') ORDER BY `key`)))) WHERE json_type(`customization`, '$.footerLinks') = 'array';
